// call after maxflow has left the residual capacities in the matrix
vector<pair<int,int>> minCut(int n, int s, vector<vector<int>>& residual) {
    vector<bool> reach(n, false);
    queue<int> q; q.push(s); reach[s] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v = 0; v < n; v++)
            if (!reach[v] && residual[u][v] > 0) { reach[v] = true; q.push(v); }
    }
    vector<pair<int,int>> cut;
    for (int u = 0; u < n; u++)
        if (reach[u])
            for (int v = 0; v < n; v++)
                if (!reach[v] && originalCap[u][v] > 0) cut.push_back({u, v});   // crossing edge
    return cut;
}

