from collections import deque
# call after maxflow has left the residual capacities in the matrix
def min_cut(n, s, residual, original_cap):
    reach = [False] * n
    reach[s] = True
    q = deque([s])
    while q:
        u = q.popleft()
        for v in range(n):
            if not reach[v] and residual[u][v] > 0:
                reach[v] = True
                q.append(v)
    cut = []
    for u in range(n):
        if reach[u]:
            for v in range(n):
                if not reach[v] and original_cap[u][v] > 0:
                    cut.append((u, v))          # crossing edge
    return cut

