// call after maxflow has left the residual capacities in residual
function minCut(n, s, residual, originalCap) {
  const reach = new Array(n).fill(false); reach[s] = true;
  const q = [s];
  while (q.length) {
    const u = q.shift();
    for (let v = 0; v < n; v++)
      if (!reach[v] && residual[u][v] > 0) { reach[v] = true; q.push(v); }
  }
  const cut = [];
  for (let u = 0; u < n; u++)
    if (reach[u])
      for (let v = 0; v < n; v++)
        if (!reach[v] && originalCap[u][v] > 0) cut.push([u, v]);   // crossing edge
  return cut;
}
